use std::{hint::black_box,time::Instant};
use unglish_core::{repair_clusters,Policy,Syllable};
struct Case { word: &'static [Syllable<'static>], banned: &'static [(u32,u32)], policy: Policy, expected: &'static [u32] }
include!("../inputs.rs");
fn fill(word:&[Syllable],banned:&[(u32,u32)],policy:Policy,out:&mut [u32])->usize {
    let mut n=0;
    for (i,cuts) in repair_clusters(word,banned,policy) {
        out[n]=i as u32;out[n+1]=cuts.coda_len as u32;out[n+2]=cuts.onset_start as u32;n+=3;
    }
    n
}
fn allocate(word:&[Syllable],banned:&[(u32,u32)],policy:Policy)->Vec<u32> {
    let count=word.windows(2).filter(|w|!w[0].coda.is_empty()&&!w[1].onset.is_empty()).count();
    let mut out=vec![0;count*3];
    fill(word,banned,policy,&mut out);
    out
}
fn run(cases:&[Case],allocated:bool,count:usize)->u64 {
    let mut out=[0;BUFFER_SIZE];let mut sum=0u64;
    for i in 0..count {
        let c=black_box(&cases[i%cases.len()]);
        if allocated {
            let v=black_box(allocate(c.word,c.banned,c.policy));let n=v.len();
            sum+=(n+if n>0{v[n-2] as usize+v[n-1] as usize}else{0}) as u64;
        } else {
            let n=fill(c.word,c.banned,c.policy,&mut out);black_box(&out[..n]);
            sum+=(n+if n>0{out[n-2] as usize+out[n-1] as usize}else{0}) as u64;
        }
    }
    black_box(sum)
}
fn measure(cases:&[Case],allocated:bool)->(Vec<f64>,Vec<u64>){
    run(cases,allocated,500000);let mut samples=Vec::new();let mut sums=Vec::new();
    for _ in 0..9 {let start=Instant::now();sums.push(run(cases,allocated,1000000));samples.push(start.elapsed().as_secs_f64()*1e9/1000000.0);}
    (samples,sums)
}
fn main(){
    for (_,cases) in SETS {for c in *cases {assert_eq!(allocate(c.word,c.banned,c.policy),c.expected);}}
    print!("{{\"sets\":{{");
    for (i,(name,cases)) in SETS.iter().enumerate(){
        if i>0 {print!(",");}print!("\"{}\":{{",name);
        for (j,(label,allocated)) in [("reused",false),("allocated",true)].iter().enumerate(){
            let (samples,sums)=measure(cases,*allocated);let mut sorted=samples.clone();sorted.sort_by(f64::total_cmp);
            if j>0 {print!(",");}print!("\"{}\":{{\"samplesNs\":{:?},\"checksums\":{:?},\"medianNs\":{}}}",label,samples,sums,sorted[4]);
        }
        print!("}}");
    }
    println!("}}}}");
}
